-- Read-only audit for Supabase E2E. Do not run against production.
select n.nspname as function_schema, p.proname as function_name, pg_get_function_identity_arguments(p.oid) as identity_arguments, format('%I.%I(%s)',n.nspname,p.proname,pg_get_function_identity_arguments(p.oid)) as full_signature, pg_get_function_result(p.oid) as return_type, l.lanname as language, r.rolname as owner, p.prosecdef as security_definer, case p.provolatile when 'i' then 'immutable' when 's' then 'stable' when 'v' then 'volatile' end as volatility, case p.proparallel when 's' then 'safe' when 'r' then 'restricted' when 'u' then 'unsafe' end as parallel_safety, p.proisstrict as strict, p.proleakproof as leakproof, coalesce(array_to_string(p.proconfig,'; '),'(none)') as proconfig, has_function_privilege('public',p.oid,'EXECUTE') as public_execute, has_function_privilege('anon',p.oid,'EXECUTE') as anon_execute, has_function_privilege('authenticated',p.oid,'EXECUTE') as authenticated_execute, has_function_privilege('service_role',p.oid,'EXECUTE') as service_role_execute, md5(regexp_replace(pg_get_functiondef(p.oid), '[[:space:]]+', ' ', 'g')) as function_definition_hash from pg_proc p join pg_namespace n on n.oid=p.pronamespace join pg_language l on l.oid=p.prolang join pg_roles r on r.oid=p.proowner where n.nspname='public' and p.prokind='f' order by p.proname,p.oid;
